#"'!/usr/bin/env python3
"""Retro Snake — a single-file curses game with power-ups and a scoreboard."""

import curses
import random
import sys
import time
from collections import deque

TITLE = "SNAKE"
MENU = [
    ("Play", "Start a new game"),
    ("High Scores", "View the local scoreboard"),
    ("Quit", "Leave the game"),
]
MIN_DELAY = 0.045   # fastest speed between moves
MAX_DELAY = 0.18    # slowest speed between moves
SPEED_STEP = 0.005  # speed up every FOOD_TO_NEXT pieces
FOOD_TO_NEXT = 4
SCORE_FILE = None   # resolved lazily (keeps module import clean)


class Pause(Exception):
    pass


class QuitGame(Exception):
    pass


def _score_path():
    """Return a per-user score file so the game works without privileges."""
    global SCORE_FILE
    if SCORE_FILE is None:
        candidates = []
        if "XDG_DATA_HOME" in __import__("os").environ and __import__("os").environ["XDG_DATA_HOME"]:
            candidates.append(__import__("os").path.join(__import__("os").environ["XDG_DATA_HOME"], "snake_scores.txt"))
        candidates.append(__import__("os").path.expanduser("~/.snake_scores.txt"))
        candidates.append(__import__("os").path.join(__import__("tempfile").gettempdir(), "snake_scores.txt"))
        for c in candidates:
            try:
                with open(c, "a"):
                    pass
                SCORE_FILE = c
                break
            except OSError:
                continue
        if SCORE_FILE is None:
            SCORE_FILE = candidates[-1]
    return SCORE_FILE


def load_scores():
    scores = []
    try:
        with open(_score_path(), "r") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    scores.append(int(line))
                except ValueError:
                    continue
    except OSError:
        return []
    scores.sort(reverse=True)
    return scores[:5]


def save_score(value):
    try:
        with open(_score_path(), "a") as fh:
            fh.write(f"{value}'"\\n\")
    except OSError:
        pass


def draw_box(win, y, x, h, w):
    try:
        curses.curs_set(0)
        win.border(0)
    except curses.error:
        pass


def center(win, text, y=None, style=None):
    h, w = win.getmaxyx()
    if y is None:
        y = h // 2
    x = max(0, (w - len(text)) // 2)
    if style:
        win.addstr(y, x, text, style)
    else:
        win.addstr(y, x, text)


class Game:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.h, self.w = stdscr.getmaxyx()

    def run(self):
        curses.curs_set(0)
        self.stdscr.keypad(True)
        curses.start_color()
        curses.use_default_colors()
        for i, color in enumerate([curses.COLOR_CYAN, curses.COLOR_GREEN,
                                   curses.COLOR_RED, curses.COLOR_YELLOW], 1):
            curses.init_pair(i, color, -1)
        while True:
            choice = self.menu()
            if choice == 0:
                self.play_round()
            elif choice == 1:
                self.scores_screen()
            else:
                return

    def menu(self):
        selected = 0
        while True:
            self.stdscr.erase()
            h, w = self.stdscr.getmaxyx()
            title_y = max(0, h // 2 - 6)
            center(self.stdscr, TITLE, title_y, curses.color_pair(1) | curses.A_BOLD)
            for i, (label, _) in enumerate(MENU):
                y = title_y + 4 + i * 2
                prefix = \"> \" if i == selected else \"  \"
                attr = curses.A_REVERSE if i == selected else curses.color_pair(2)
                center(self.stdscr, f\"{prefix}{label}\", y, attr)
            center(self.stdscr, \"Arrows/WASD to move  |  P to pause  |  Q to quit\",
                   h - 1, curses.A_DIM)
            enough = (w >= 40 and h >= 20)
            if not enough:
                center(self.stdscr, \"Window too small — make it at least 40x20\", h - 2, curses.color_pair(3))
            self.stdscr.refresh()
            key = self.stdscr.getkey()
            if key in (\"KEY_UP\", \"k\"):
                selected = (selected - 1) % len(MENU)
            elif key in (\"KEY_DOWN\", \"j\"):
                selected = (selected + 1) % len(MENU)
            elif key in (\"\\n\", \"\\r\", \" \"):
                return selected
            elif key in (\"q\", \"Q\"):
                return 2

    def scores_screen(self):
        self.stdscr.erase()
        h, w = self.stdscr.getmaxyx()
        center(self.stdscr, \"HIGH SCORES\", max(0, h // 2 - 5), curses.color_pair(1) | curses.A_BOLD)
        scores = load_scores()
        if not scores:
            center(self.stdscr, \"No scores yet — go play"'!", h // 2, curses.A_DIM)
        else:
            for i, score in enumerate(scores, 1):
                rank = {1: "1st", 2: "2nd", 3: "3rd"}.get(i, f"{i}th")
                center(self.stdscr, f"{rank:>3}  {score}", h // 2 - 2 + i, curses.color_pair(2))
        center(self.stdscr, "Press any key to return", h - 1, curses.A_DIM)
        self.stdscr.refresh()
        self.stdscr.getkey()

    def play_round(self):
        h, w = self.stdscr.getmaxyx()
        pad = 2
        box_h, box_w = h - pad * 2 - 1, w - pad * 2
        if box_h < 5 or box_w < 8:
            self.stdscr.erase()
            center(self.stdscr, "Window too small to play", h // 2, curses.color_pair(3))
            center(self.stdscr, "Enlarge the terminal and press any key", h // 2 + 1)
            self.stdscr.refresh()
            self.stdscr.getkey()
            return
        # Playfield coordinates (1..box_h, 1..box_w) inside the bordered box at (pad, pad).
        top, left = pad, pad
        if self.w < 24 or self.h < 12:
            pass
        play_h, play_w = box_h - 1, box_w - 1  # inner area without the border

        def px(x):
            return left + 1 + x

        def py(y):
            return top + 1 + y

        snake = deque([(play_w // 2, play_h // 2)])
        direction = (1, 0)
        grow = 0
        delay = MAX_DELAY
        pieces = 0
        bonus = False
        score = 0

        def free_positions():
            occupied = set(snake)
            out = []
            for yy in range(play_h):
                for xx in range(play_w):
                    if (xx, yy) not in occupied:
                        out.append((xx, yy))
            return out

        def place_food():
            free = free_positions()
            if not free:
                return None
            return random.choice(free)

        # Place initial food not under the snake.
        food = place_food()
        while food == snake[0]:
            food = place_food()

        self.stdscr.erase()
        draw_box(self.stdscr, top, left, box_h, box_w)
        self.stdscr.nodelay(True)

        def draw():
            self.stdscr.move(py(snake[0][1]), px(snake[0][0]))
            for idx, (x, y) in enumerate(snake):
                attr = curses.color_pair(1) if idx == 0 else curses.color_pair(2)
                try:
                    self.stdscr.addch(py(y), px(x), "@" if idx == 0 else "o", attr)
                except curses.error:
                    pass
            if food:
                try:
                    self.stdscr.addch(py(food[1]), px(food[0]),
                                      "*", curses.color_pair(3) | curses.A_BOLD)
                except curses.error:
                    pass
            header = f"Score {score}"
            if bonus:
                header += "  BONUS!"
            self.stdscr.addstr(0, 1, header)
            self.stdscr.addstr(0, self.w - 8, f" len {len(snake)}")
            self.stdscr.refresh()

        draw()
        changed = True
        while True:
            if changed:
                draw()
            changed = False
            key = None
            # Timer for non-blocking input at the current speed.
            self.stdscr.timeout(int(delay * 1000))
            try:
                key = self.stdscr.getkey()
            except curses.error:
                key = None
            self.stdscr.timeout(-1)
            if key:
                if key in ("q", "Q"):
                    raise QuitGame
                if key in ("p", "P", " "):
                    self.pause()
                    continue
                new_dir = direction
                if key in ("KEY_UP", "k"):
                    new_dir = (0, -1)
                elif key in ("KEY_DOWN", "j"):
                    new_dir = (0, 1)
                elif key in ("KEY_LEFT", "h"):
                    new_dir = (-1, 0)
                elif key in ("KEY_RIGHT", "l"):
                    new_dir = (1, 0)
                if new_dir != (0, 0) and (new_dir[0], new_dir[1]) != (-direction[0], -direction[1]):
                    direction = new_dir
                    changed = True
            # Advance the snake.
            head = snake[0]
            nhead = (head[0] + direction[0], head[1] + direction[1])
            hit_wall = not (0 <= nhead[0] < play_w and 0 <= nhead[1] < play_h)
            hit_self = nhead in snake
            if hit_wall or hit_self:
                break
            snake.appendleft(nhead)
            if bonus:
                snake.appendleft((nhead[0] + direction[0], nhead[1] + direction[1]))
                bonus = False
            if nhead == food:
                score += 1
                pieces += 1
                grow += 1
                if pieces % FOOD_TO_NEXT == 0:
                    delay = max(MIN_DELAY, delay - SPEED_STEP)
                food = place_food()
                if random.random() < 0.2 and play_w * play_h > 25:
                    bonus = True
            else:
                if grow:
                    grow -= 1
                else:
                    snake.pop()
            if len(snake) >= play_w * play_h:
                break
            self.stdscr.nodelay(True)
            draw()
            changed = False

        self.stdscr.nodelay(False)
        save_score(score)
        self.game_over(score)

    def pause(self):
        h, w = self.stdscr.getmaxyx()
        self.stdscr.nodelay(False)
        self.stdscr.erase()
        draw_box(self.stdscr, 0, 0, h, w) if h > 2 and w > 2 else None
        center(self.stdscr, "PAUSED", h // 2 - 1, curses.color_pair(1) | curses.A_BOLD)
        center(self.stdscr, "Press P or Space to resume", h // 2 + 1, curses.A_DIM)
        self.stdscr.refresh()
        while True:
            try:
                key = self.stdscr.getkey()
            except curses.error:
                key = None
                continue
            if key in ("p", "P", " ", "'"\\n\"):
                return

    def pause_old(self):
        pass

    def game_over(self, score):
        h, w = self.stdscr.getmaxyx()
        old = load_scores()
        is_best = old and score > old[0]
        self.stdscr.erase()
        best_line = \"\"
        if old:
            best_line = f\"Best: {old[0]}\"
        center(self.stdscr, \"GAME OVER\", h // 2 - 3, curses.color_pair(3) | curses.A_BOLD)
        center(self.stdscr, f\"Score: {score}\", h // 2, curses.color_pair(2))
        if best_line:
            center(self.stdscr, best_line, h // 2 + 1, curses.A_DIM)
        if is_best:
            center(self.stdscr, \"NEW HIGH SCORE"'!", h // 2 + 2, curses.color_pair(1) | curses.A_BOLD)
        center(self.stdscr, "Press any key for menu", h - 1, curses.A_DIM)
        self.stdscr.refresh()
        self.stdscr.nodelay(False)
        self.stdscr.getkey()


def main(stdscr):
    Game(stdscr).run()


if __name__ == "__main__":
    try:
        curses.wrapper(main)
    except QuitGame:
        pass
    except KeyboardInterrupt:
        pass
